#!/usr/bin/env python3
"""INT-09 composite photo-edit request intake rights audit.

Reads /app/input, applies INT-09 rev 4 as of 2026-03-31, and writes the
three data deliverables to /app. The memo is written separately.
"""
import csv
import json
from datetime import date

INPUT = "/app/input"
OUT = "/app"
AUDIT_DATE = date(2026, 3, 31)

PUBLIC_PAID = {"social_public", "print_for_sale"}


def load_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def parse_date(s):
    s = s.strip()
    if not s or s == "none":
        return None
    y, m, d = s.split("-")
    return date(int(y), int(m), int(d))


def dist_list(s):
    s = s.strip()
    if s == "none" or not s:
        return []
    return [x.strip() for x in s.split(";") if x.strip()]


# ---- licence register with supersession ----
reg_rows = load_csv(f"{INPUT}/licensed_property_register.csv")
register = {r["license_id"]: r for r in reg_rows}

# old_id -> new_id (a row's `supersedes` points to the id it replaces)
superseded_by = {}
for r in reg_rows:
    if r["supersedes"].strip() != "none":
        superseded_by[r["supersedes"].strip()] = r["license_id"]


def governing(cited_id):
    """Follow the supersession chain to the governing row for a cited licence id."""
    cur = cited_id
    seen = set()
    while cur in superseded_by and cur not in seen:
        seen.add(cur)
        cur = superseded_by[cur]
    return register.get(cur)


def covers(cited_id, need_type, distribution):
    """§2: does a licence of need_type cover this request's distribution?"""
    if cited_id is None or cited_id == "none":
        return False, None
    if cited_id not in register:        # rule 1
        return False, None
    gov = governing(cited_id)
    if gov is None:
        return False, None
    if gov["license_type"].strip() != need_type:        # rule 2
        return False, gov
    covers_d = dist_list(gov["covers_distribution"])
    if "all" not in covers_d and distribution not in covers_d:   # rule 3
        return False, gov
    vu = parse_date(gov["valid_until"])
    if vu is None or vu < AUDIT_DATE:        # rule 4 (on/after audit date = current)
        return False, gov
    return True, gov


def audit_request(r, accounts):
    findings = []
    dist = r["intended_distribution"].strip()

    # §3 Licensed-character use
    char = r["character_property"].strip()
    if char != "none":
        if dist == "personal_only":
            pass  # personal-use allowance clears §3 entirely
        else:
            cov, gov = covers(r["character_license_id"].strip(), "character", dist)
            if not cov:
                findings.append("UNLICENSED_CHARACTER_USE")
            else:
                cap = gov["max_character_area_pct"].strip()
                if cap != "none":
                    cap = float(cap)
                    area = float(r["character_px_area"]) / float(r["canvas_px_area"]) * 100.0
                    if area > cap + 1e-9:
                        findings.append("UNLICENSED_CHARACTER_USE")

    # §4 Third-party backgrounds
    bsrc = r["background_source"].strip()
    if bsrc == "third_party_unlicensed":
        findings.append("THIRD_PARTY_BACKGROUND_UNLICENSED")
    elif bsrc == "third_party_licensed":
        cov, gov = covers(r["background_license_id"].strip(), "background", dist)
        if not cov:
            findings.append("THIRD_PARTY_BACKGROUND_UNLICENSED")
    # customer_original -> never

    # §5 Minor consent
    if r["subject_is_minor"].strip() == "True":
        ctype = r["minor_consent_type"].strip()
        vu = parse_date(r["minor_consent_valid_until"])
        present = ctype != "none"
        current = vu is not None and vu >= AUDIT_DATE
        if ctype == "publicity":
            wide = True
        elif ctype == "basic":
            wide = dist in ("personal_only", "client_internal")
        else:
            wide = False
        if not (present and current and wide):
            findings.append("MISSING_MINOR_CONSENT")

    # §6 Commercial distribution routing
    if dist in PUBLIC_PAID:
        acc = accounts[r["account_id"].strip()]
        if acc["agreement_status"].strip() != "active":
            cleared = False
        else:
            cleared = dist in dist_list(acc["master_agreement_covers"])
        if not cleared:
            findings.append("COMMERCIAL_DISTRIBUTION_FLAG")

    # §7 Alteration disclosure
    if r["alteration_level"].strip() == "substantive" and dist in PUBLIC_PAID:
        if r["alteration_disclosure_on_file"].strip() != "True":
            findings.append("ALTERATION_DISCLOSURE_MISSING")

    # stable order: §3,§4,§5,§6,§7
    order = ["UNLICENSED_CHARACTER_USE", "THIRD_PARTY_BACKGROUND_UNLICENSED",
             "MISSING_MINOR_CONSENT", "COMMERCIAL_DISTRIBUTION_FLAG",
             "ALTERATION_DISCLOSURE_MISSING"]
    findings = [f for f in order if f in findings]
    return findings


def main():
    log = load_csv(f"{INPUT}/composite_request_log.csv")
    accounts = {a["account_id"].strip(): a for a in load_csv(f"{INPUT}/client_accounts.csv")}

    # audited = not withdrawn
    audited = [r for r in log if r["intake_status"].strip() != "withdrawn"]
    withdrawn = [r for r in log if r["intake_status"].strip() == "withdrawn"]

    per_req = {}
    for r in audited:
        per_req[r["request_id"].strip()] = audit_request(r, accounts)

    # ---- §8 account escalation ----
    batch_total = len(audited)
    flagged_total = sum(1 for f in per_req.values() if f)
    batch_share = flagged_total / batch_total if batch_total else 0.0

    account_rows = {}
    for acc_id, acc in accounts.items():
        reqs = [rid for rid in per_req if log_req(log, rid)["account_id"].strip() == acc_id]
        # only accounts that actually hold audited requests appear
        if not reqs:
            continue
        cnt = len(reqs)
        flagged = sum(1 for rid in reqs if per_req[rid])
        share = flagged / cnt if cnt else 0.0
        any_three = any(len(per_req[rid]) >= 3 for rid in reqs)
        esc = share > batch_share or any_three
        account_rows[acc_id] = {
            "account_type": acc["account_type"].strip(),
            "request_count": cnt,
            "flagged_requests": flagged,
            "escalation": "ESCALATION_REQUIRED" if esc else "none",
        }

    # ---- §9 figures ----
    finding_total = sum(len(f) for f in per_req.values())

    def count_with(code):
        return sum(1 for f in per_req.values() if code in f)

    figures = {
        "request_count": batch_total,
        "account_count": len(account_rows),
        "flagged_count": flagged_total,
        "compliant_count": batch_total - flagged_total,
        "finding_total": finding_total,
        "character_count": count_with("UNLICENSED_CHARACTER_USE"),
        "background_count": count_with("THIRD_PARTY_BACKGROUND_UNLICENSED"),
        "consent_count": count_with("MISSING_MINOR_CONSENT"),
        "commercial_count": count_with("COMMERCIAL_DISTRIBUTION_FLAG"),
        "disclosure_count": count_with("ALTERATION_DISCLOSURE_MISSING"),
        "escalated_accounts": sum(1 for a in account_rows.values()
                                  if a["escalation"] == "ESCALATION_REQUIRED"),
    }

    # ---- write composite_request_audit.csv ----
    with open(f"{OUT}/composite_request_audit.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["request_id", "finding"])
        for rid in sorted(per_req, key=rid_key):
            w.writerow([rid, "|".join(per_req[rid]) if per_req[rid] else "none"])

    # ---- write account_summary.csv ----
    with open(f"{OUT}/account_summary.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["account_id", "account_type", "request_count",
                    "flagged_requests", "escalation"])
        for acc_id in sorted(account_rows):
            a = account_rows[acc_id]
            w.writerow([acc_id, a["account_type"], a["request_count"],
                        a["flagged_requests"], a["escalation"]])

    # ---- write results.json ----
    with open(f"{OUT}/results.json", "w") as f:
        json.dump(figures, f, indent=2)
        f.write("\n")

    # ---- report to stdout for cross-check ----
    print("AUDIT DATE:", AUDIT_DATE)
    print("WITHDRAWN (excluded):", [r["request_id"].strip() for r in withdrawn])
    print("\nPER-REQUEST FINDINGS:")
    for rid in sorted(per_req, key=rid_key):
        print(f"  {rid}: {'|'.join(per_req[rid]) if per_req[rid] else 'none'}"
              f"  ({len(per_req[rid])})")
    print("\nACCOUNT ROLLUP:")
    for acc_id in sorted(account_rows):
        a = account_rows[acc_id]
        print(f"  {acc_id} {a['account_type']}: cnt={a['request_count']} "
              f"flag={a['flagged_requests']} esc={a['escalation']}")
    print(f"\nbatch_share = {flagged_total}/{batch_total} = {batch_share:.4f}")
    print("\nFIGURES:", json.dumps(figures, indent=2))


def log_req(log, rid):
    for r in log:
        if r["request_id"].strip() == rid:
            return r
    raise KeyError(rid)


def rid_key(rid):
    return int(rid.split("-")[1])


if __name__ == "__main__":
    main()

